# Simpler approach: output grid same shape, check both sides
output = []
for r in range(24):
    row = []
    for c in range(11):
        if c == 5:
            row.append(6)
        else:
            # For each position, check if both left and right have 0 at that mirrored position
            left_c = c if c < 5 else c - 6
            if left[r][left_c] == 0 and right[r][left_c] == 0:
                row.append(0)
            else:
                row.append(5)
    output.append(row)

print("Output grid:")
for row in output:
    print(row)

# Try OR pattern - 0 if either side has 0
right = [[c for c in row[6:]] for row in grid]
left = [[c for c in row[:5]] for row in grid]

output = []
for r in range(24):
    row = []
    for c in range(11):
        if c == 5:
            row.append(6)
        else:
            left_c = c if c < 5 else c - 6
            # OR: 0 if at least one side has 0
            left_0 = left[r][left_c] == 0
            right_0 = right[r][left_c] == 0
            if left_0 or right_0:
                row.append(0)
            else:
                row.append(5)
    output.append(row)

print("OR output:")
for row in output:
    print(row)

